export class ManageJobsComponent {
  adminService = inject(AdminService);
  cdr = inject(ChangeDetectorRef);
  assetsUrl = environment.assetsUrl;
  jobsList = [];
  isLoading = false;
  searchTerm = '';
  selectedJob = null;
  showJobCard = false;
  isJobEditMode = false;
  jobEditData = {};
  get filteredJobs() {
    if (!this.searchTerm || !this.searchTerm.trim()) {
      return this.jobsList;
    }
    const q = this.searchTerm.toLowerCase();
    return this.jobsList.filter(job => (job.title || '').toLowerCase().includes(q) || (job.company_name || '').toLowerCase().includes(q) || (job.location || '').toLowerCase().includes(q) || (job.contract_type || '').toLowerCase().includes(q));
  }
  ngOnInit() {
    this.isLoading = true;
    this.adminService.getAllJobs().subscribe({
      next: data => {
        this.jobsList = data;
        this.isLoading = false;
        this.cdr.detectChanges();
      },
      error: () => this.isLoading = false
    });
  }
  onDeleteJob(jobId) {
    if (confirm("⚠️ Êtes-vous sûr de vouloir supprimer définitivement cette offre d'emploi ?")) {
      this.adminService.deleteJob(jobId).subscribe({
        next: () => {
          this.jobsList = this.jobsList.filter(job => job.id !== jobId);
          this.cdr.detectChanges();
        },
        error: err => alert("Erreur lors de la suppression : " + (err.error?.message || err.message))
      });
    }
  }
  openJobCard(job) {
    this.selectedJob = {
      ...job
    };
    this.jobEditData = {
      ...job
    };
    this.isJobEditMode = false;
    this.showJobCard = true;
  }
  closeJobCard() {
    this.showJobCard = false;
    this.selectedJob = null;
  }
  toggleJobEditMode(mode) {
    this.isJobEditMode = mode;
    if (!mode) {
      this.jobEditData = {
        ...this.selectedJob
      }; // Réinitialise les données d'édition si on annule
    }
  }
  onSaveJobEdit() {
    this.adminService.updateJob(this.jobEditData.id, this.jobEditData).subscribe({
      next: res => {
        const updatedJob = res.job || res;
        const index = this.jobsList.findIndex(j => j.id === updatedJob.id);
        if (index !== -1) {
          this.jobsList[index] = {
            ...updatedJob
          };
        }
        this.selectedJob = {
          ...updatedJob
        };
        this.isJobEditMode = false;
        this.cdr.detectChanges();
        alert("Offre d'emploi mise à jour !");
      },
      error: err => alert("Erreur : " + (err.error?.message || "Impossible de mettre à jour l'offre."))
